import{_ as t,o as a,c as e,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Add Comments On Task","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/spec.md","filePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/spec.md"}'),o={name:"feature/content-task-workflow/3-6-3-add-comments-on-task/spec.md"};function h(s,n,c,r,l,u){return a(),e("div",null,[...n[0]||(n[0]=[i(`<h1 id="uc-—-add-comments-on-task" tabindex="-1">UC — Add Comments On Task <a class="header-anchor" href="#uc-—-add-comments-on-task" aria-label="Permalink to &quot;UC — Add Comments On Task&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.3</td></tr><tr><td>Feature</td><td>Add Comments On Task</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT, MANAGER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Đã triển khai ứng dụng 2026-10-17; đã kiểm tra cô lập, chờ kiểm thử S3/inbox thật và team review</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Chốt thực thi 2026-10-17: không có QC/review chéo; Owner tham gia bằng membership Manager thực tế trong Workspace. Bình luận Task tách biệt nhận xét duyệt nội dung trong task_approvals. Theo yêu cầu người dùng, không thêm/commit file test dưới src.</p><p>Cho phép nhận xét, yêu cầu chỉnh sửa trên Task — dùng chung cho cả 3 role tham gia.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator, Client, hoặc Manager, tôi muốn bình luận trên 1 Task, để trao đổi/yêu cầu chỉnh sửa trực tiếp trong luồng công việc.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Textarea nhập comment, hỗ trợ mention (@user), có thể đính kèm ảnh/link tham khảo.</li><li>Comment hiển thị theo timeline, kèm tên + role người comment + timestamp.</li><li>Vẫn cho tạo comment mới trên Task COMPLETED/CANCELLED nếu người dùng còn quyền Workspace/Task. Comment không mở lại Task, Campaign hoặc vòng approval.</li><li>Ảnh cho phép JPEG/PNG/WebP, tối đa 5 ảnh mỗi comment và 5 MB mỗi ảnh; kiểm tra ở UI và API, định dạng thực chứ không chỉ tên file.</li><li>Q13 confirmed 2026-10-14: Client active được xem và bình luận mọi Task cùng Workspace, kể cả Task thủ công và Task cũ, không phân biệt nội bộ/thường. Lịch sử bình luận và ảnh đã ATTACHED cũng theo quyền Workspace; upload DRAFT vẫn chỉ chủ upload được preview. Không mở quyền người ngoài hoặc đã rời Workspace.</li><li>Mention chỉ tới người có quyền Task và đang hoạt động trong Workspace; không coi một URL ảnh bất kỳ là attachment đã có quyền sử dụng.</li><li>Thông báo in-app tới người được mention, Creator phụ trách và Manager của Workspace; bỏ trùng, bỏ tác giả và chỉ gửi người còn quyền Task. Client chỉ nhận khi được mention (Q11 confirmed); không gửi email hoặc thông báo mọi Client trong Workspace. Không lấy người QC lịch sử làm người nhận.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Bình luận nằm dưới thông tin Task trong hộp chi tiết hiện có; không đổi layout/editor của thành viên khác.</li><li>Nút Nhắc tên mở ngay danh sách tìm thành viên; chọn để thêm tên và người nhận thông báo. Nút ảnh mở trình chọn JPEG/PNG/WebP, có tiến trình tải, xem trước và bỏ ảnh nháp.</li><li>Gõ <code>@</code> ở đầu dòng hoặc sau khoảng trắng ngay trong bình luận mở gợi ý thành viên; gõ tiếp để tìm. Không mở khi nhập email. Chọn bằng chuột hoặc ↑/↓ + Enter; Escape đóng gợi ý, không đóng Task. Giữ con trỏ trong ô nhập, thay đúng đoạn @ đang gõ, không xóa phần văn bản phía sau và không gửi bình luận khi Enter đang chọn tên. Khi đang gõ bộ chữ tiếng Việt (IME), Enter không chọn tên/gửi nhầm. Chỉ tên được chọn từ gợi ý mới thêm User ID mention; không tự biến mọi @text thành thông báo.</li><li>Theo yêu cầu UX bổ sung: dropdown nổi bám vị trí dấu @ đang nhập, không chiếm chỗ thành một khối dưới ô. Tự tránh mép/đổi hướng khi thiếu chỗ. Thành viên hiển thị tên, vai trò và initials (API hiện không trả avatar); không bịa ảnh đại diện.</li><li>Trong ô soạn, mention đã chọn là nhãn inline có nền nổi bật, gắn User ID, không phải đoạn @text tùy ý. Xóa/cắt nhãn sẽ bỏ người nhận nếu không còn nhãn nào của người đó; Undo khôi phục cả nhãn và liên kết. Không còn danh sách chip nhắc tên rời bên dưới. Copy/paste vào ô chỉ nhận văn bản, không nhận HTML/mention ID giả. Sau khi gửi vẫn giữ contract plain text + mentions User IDs hiện tại; chưa bổ sung vị trí/nhãn snapshot cho lịch sử comment cũ trong đợt UI này.</li><li>Giữ nội dung/ảnh hợp lệ khi gửi lỗi; retry cùng nội dung không tạo trùng. Hiển thị xác nhận trước khi đóng nếu có bản nháp chưa gửi, dùng dialog của ứng dụng, không dùng thông báo mặc định trình duyệt.</li><li>Timeline có tải lịch sử cũ và Làm mới; đợt này không mở rộng thành comment realtime qua WebSocket.</li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/comments</span></span>
<span class="line"><span>{ &quot;content&quot;: &quot;string&quot;, &quot;mentions&quot;?: [&quot;User UUID&quot;], &quot;attachmentIds&quot;?: [&quot;owned upload ID&quot;], &quot;clientRequestId&quot;: &quot;UUID&quot; }</span></span>
<span class="line"><span>→ 201 { &quot;success&quot;: true, &quot;data&quot;: { &quot;id&quot;, &quot;content&quot;, &quot;authorId&quot;, &quot;createdAt&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/comments?limit=30&amp;cursor=...</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;items&quot;: [{...}], &quot;nextCursor&quot;: &quot;string|null&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/comment-members?search=&amp;page=0</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;items&quot;: [{ &quot;userId&quot;, &quot;displayName&quot;, &quot;role&quot; }], &quot;hasMore&quot;: false } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/comment-uploads (multipart file)</span></span>
<span class="line"><span>→ 201 { &quot;success&quot;: true, &quot;data&quot;: { &quot;id&quot;, &quot;name&quot;, &quot;contentType&quot;, &quot;byteSize&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/comment-uploads/{id}/content</span></span>
<span class="line"><span>→ 200 private image bytes, Cache-Control: no-store</span></span></code></pre></div><p>attachmentIds thay arbitrary URL để kiểm tra ownership; clientRequestId chống gửi trùng. Tác giả/role lấy phía server. content bắt buộc không rỗng, tối đa 10.000 ký tự, lưu plain text; HTTP(S) link an toàn do UI render. Không dùng Chat Workspace thay lịch sử bình luận theo Task. Chi tiết phân trang và giới hạn kỹ thuật xem <a href="./../task-comments-implementation-2026-10-17.html">setup</a>.</p><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không có quyền truy cập Task này (không thuộc Workspace) → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Client comment trên Task không yêu cầu Client duyệt → vẫn cho phép nếu còn active cùng Workspace. Cờ requiresClientApproval chỉ cấu hình duyệt kết quả, không quyết định quyền bình luận.</li><li>Task terminal vẫn được comment; người bị gỡ khỏi Workspace không được gửi/xem tiếp dù từng tham gia thread.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Comment tạo/hiển thị đúng thứ tự thời gian.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Edit/xóa comment sau khi đã gửi (không có trong CSV, có thể bổ sung sau).</li></ul><h2 id="i18n-va-theme" tabindex="-1">i18n và theme <a class="header-anchor" href="#i18n-va-theme" aria-label="Permalink to &quot;i18n và theme&quot;">​</a></h2><p>Composer/timeline/mention/upload dùng <code>tasks.comments.*</code>; lỗi API dùng <code>tasks.workflow.errors.*</code> vi/en song song trong <code>src/i18n/locales/{vi,en}/tasks.json</code>. Semantic light/dark, bàn phím và layout mobile. Có loading/empty/forbidden/upload progress/error/success; lỗi upload/submit giữ draft, retry không tạo comment trùng. Xem <a href="./plan.html">plan</a>, <a href="./task.html">task</a>, <a href="./test.html">test</a>.</p><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../ba/05-content-task-workflow.html">05-content-task-workflow.md</a>, <a href="./../task-detail-assignment-comments-roadmap.html">roadmap</a>.</p>`,26)])])}const m=t(o,[["render",h]]);export{p as __pageData,m as default};
